    expect(result.behavior === "allow" && result.updatedPermissions).not.toBe(suggestions);
  });

  it("distinguishes explicit reject from cancellation", () => {
    expect(
      permissionResult(
        { outcome: { outcome: "selected", optionId: PERMISSION_OPTION_ID.reject } },
        "Bash",
        {},
        "tool-3",
