    ).toThrow("Tool use aborted");
  });

  it("fails closed for an unavailable or unknown selection", () => {
    expect(() =>
      permissionResult(
        { outcome: { outcome: "selected", optionId: PERMISSION_OPTION_ID.allowWithUpdates } },
        "Bash",
        {},
        "tool-4",
        build("Bash"),
      ),
    ).toThrow("Permission option was not offered");
