import { describe, it, expect, vi } from "vitest";
import type { Logger } from "../acp-agent.js";
import { resolvePermissionMode } from "../permissions/modes.js";

function mockLogger() {
  const error = vi.fn<(...args: any[]) => void>();
  const log = vi.fn<(...args: any[]) => void>();
  const logger: Logger = { log, error };
  return { logger, error, log };
}

describe("resolvePermissionMode", () => {
  it("returns 'default' when no mode is provided", () => {
    expect(resolvePermissionMode()).toBe("default");
    expect(resolvePermissionMode(undefined)).toBe("default");
  });

  it("resolves exact canonical modes", () => {
    expect(resolvePermissionMode("default")).toBe("default");
    expect(resolvePermissionMode("acceptEdits")).toBe("acceptEdits");
    expect(resolvePermissionMode("dontAsk")).toBe("dontAsk");
    expect(resolvePermissionMode("plan")).toBe("plan");
    expect(resolvePermissionMode("bypassPermissions", console, true)).toBe("bypassPermissions");
  });

  it("resolves case-insensitive aliases", () => {
    expect(resolvePermissionMode("DontAsk")).toBe("dontAsk");
    expect(resolvePermissionMode("DONTASK")).toBe("dontAsk");
    expect(resolvePermissionMode("AcceptEdits")).toBe("acceptEdits");
    expect(resolvePermissionMode("bypass", console, true)).toBe("bypassPermissions");
  });

  it("clamps bypassPermissions to 'default' and logs when bypass is not allowed", () => {
    const { logger, error } = mockLogger();
    expect(resolvePermissionMode("bypassPermissions", logger, false)).toBe("default");
    expect(error).toHaveBeenCalledWith(expect.stringContaining("bypassPermissions"));
  });

  it("resolves 'manual' as an alias for 'default'", () => {
    const { logger, error } = mockLogger();
    expect(resolvePermissionMode("manual", logger)).toBe("default");
    expect(resolvePermissionMode("Manual", logger)).toBe("default");
    expect(error).not.toHaveBeenCalled();
  });

  it("trims whitespace", () => {
    expect(resolvePermissionMode("  dontAsk  ")).toBe("dontAsk");
  });

  it("falls back to 'default' and logs on non-string values", () => {
    for (const value of [123, true, {}]) {
      const { logger, error } = mockLogger();
      expect(resolvePermissionMode(value, logger)).toBe("default");
      expect(error).toHaveBeenCalledWith(expect.stringContaining("expected a string"));
    }
  });

  it("falls back to 'default' and logs on empty string", () => {
    for (const value of ["", "  "]) {
      const { logger, error } = mockLogger();
      expect(resolvePermissionMode(value, logger)).toBe("default");
      expect(error).toHaveBeenCalledWith(expect.stringContaining("expected a non-empty string"));
    }
  });

  it("falls back to 'default' and logs on unknown mode", () => {
    const { logger, error } = mockLogger();
    expect(resolvePermissionMode("yolo", logger)).toBe("default");
    expect(error).toHaveBeenCalledWith(expect.stringContaining("yolo"));
  });
});

import { beforeEach, describe, expect, it } from "vitest";
import type { SessionNotification } from "@agentclientprotocol/sdk";
import { ClaudeAcpAgent, type AcpClient } from "../acp-agent.js";
import { makeMockQuery } from "./helpers.js";

const SESSION_ID = "test-session-id";

describe("session permission updates", () => {
  let agent: ClaudeAcpAgent;
  let capturedPermissionRequest: any;
  let permissionResponse: any;
  let sessionUpdates: SessionNotification[];

  beforeEach(() => {
    capturedPermissionRequest = null;
    permissionResponse = { outcome: { outcome: "cancelled" } };
    sessionUpdates = [];
    const client = {
      sessionUpdate: async (notification: SessionNotification) => {
        sessionUpdates.push(notification);
      },
      requestPermission: async (params: any) => {
        capturedPermissionRequest = params;
        return permissionResponse;
      },
      readTextFile: async () => ({ content: "" }),
      writeTextFile: async () => ({}),
    } as unknown as AcpClient;
    agent = new ClaudeAcpAgent(client);

    agent.sessions[SESSION_ID] = {
      query: makeMockQuery(),
      cwd: process.cwd(),
      modes: {
        currentModeId: "plan",
        availableModes: [
          { id: "default", name: "Manual" },
          { id: "acceptEdits", name: "Accept edits" },
          { id: "plan", name: "Plan" },
        ],
      },
      models: { currentModelId: "opus", availableModels: [] },
      modelInfos: [],
      configOptions: [],
      emittedToolCalls: new Set(["toolu_1"]),
      contextWindowSize: 200_000,
      toolUseCache: {},
    } as any;
  });

  it("maps an ExitPlanMode choice to the selected session mode effect", async () => {
    permissionResponse = { outcome: { outcome: "selected", optionId: "exit-plan-default" } };

    const result = await (agent as any).canUseTool(SESSION_ID)(
      "ExitPlanMode",
      { plan: "do stuff" },
      { signal: new AbortController().signal, toolUseID: "toolu_1" },
    );

    expect(capturedPermissionRequest.options.map((option: any) => option.optionId)).toEqual([
      "exit-plan-default",
      "exit-plan-clear-accept-edits",
      "exit-plan-accept-edits",
      "reject",
    ]);
    // A client that is not AIR gets no permission presentation.
    expect(capturedPermissionRequest._meta).toBeUndefined();
    expect(result.updatedPermissions).toEqual([
      { type: "setMode", mode: "default", destination: "session" },
    ]);
    expect(agent.sessions[SESSION_ID].modes.currentModeId).toBe("default");
    expect(sessionUpdates).toEqual([
      {
        sessionId: SESSION_ID,
        update: { sessionUpdate: "current_mode_update", currentModeId: "default" },
      },
      {
        sessionId: SESSION_ID,
        update: { sessionUpdate: "config_option_update", configOptions: [] },
      },
    ]);
  });

  it("falls an Auto permission effect back when the current model cannot use Auto", async () => {
    const session = agent.sessions[SESSION_ID];
    session.modes.availableModes.push({ id: "auto", name: "Auto" });
    session.models.currentModelId = "haiku";
    session.modelInfos = [{ value: "haiku", displayName: "Haiku", description: "" }];
    permissionResponse = { outcome: { outcome: "selected", optionId: "exit-plan-auto" } };

    const result = await (agent as any).canUseTool(SESSION_ID)(
      "ExitPlanMode",
      { plan: "do stuff" },
      { signal: new AbortController().signal, toolUseID: "toolu_1" },
    );

    expect(result.updatedPermissions).toEqual([
      { type: "setMode", mode: "acceptEdits", destination: "session" },
    ]);
    expect(
      sessionUpdates.filter(
        (notification) => notification.update.sessionUpdate === "agent_message_chunk",
      ),
    ).toHaveLength(1);
  });
});

